import{_ as e,o as a,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Meditation and Concentration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/magic/meditation-and-concentration.md","filePath":"guide/magic/meditation-and-concentration.md"}'),o={name:"guide/magic/meditation-and-concentration.md"};function r(s,t,c,d,l,m){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="meditation-and-concentration" tabindex="-1">Meditation and Concentration <a class="header-anchor" href="#meditation-and-concentration" aria-label="Permalink to &quot;Meditation and Concentration&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><p><a href="/Syrolands-Public/game-design/magic.html#meditation-and-concentration">Full design specification</a></p><p>Meditation is proposed as mental organization as well as resource recovery: preparing difficult patterns, arranging Active Memory, recovering readiness and using learned mental states with trade-offs.</p><p>Concentration concerns stability under pressure. Damage, movement, local trauma, repeated attacks, fatigue, difficult variants and certain effects may disrupt a cast. It is not automatically another skill that consumes the skillcap.</p><p>Fizzle means failing to execute a pattern correctly; interruption means pressure disrupts an attempt. Their costs and formulas remain undecided. More mana alone would not make an injured, pressured mage equivalent to an undisturbed one.</p><p>No trance list or numeric bonus is finalized. <a href="/Syrolands-Public/guide/magic/memory-and-familiarity.html">Memory preparation</a> and <a href="/Syrolands-Public/guide/combat/stamina-and-reactive-combat.html">combat pressure</a> connect to this proposal without changing the current combat experiment.</p><p><a href="/Syrolands-Public/game-design/magic.html">Related design specification</a></p>',8)])])}const g=e(o,[["render",r]]);export{u as __pageData,g as default};
